@Service
@Transactional(readOnly = true)
@RequiredArgsConstructor
public class MemberQueryService {

    private final MemberRepository memberRepository;

    public Page<MemberDto> list(Pageable pageable) {
        return memberRepository.findWithTeamBy(pageable).map(MemberDto::of);
    }

    @Transactional          // 여기만 다시 연다
    public void rename(Long id, String name) {
        memberRepository.findById(id).orElseThrow().setUsername(name);
    }
}

@Test
void 섞어_쓰기() {
    memberQueryService.list(PageRequest.of(0, 2));
    memberQueryService.rename(1L, "바꿈");
}

