-- 같은 클래스 안에서 부르면

@Service
@Transactional(readOnly = true)
public class SelfCallService {

    public void outer(Long id) {
        inner(id);              // this.inner 다
    }

    @Transactional
    public void inner(Long id) {
        memberRepository.findById(id).orElseThrow().setUsername("자기호출");
    }
}

@Test
void 자기_호출() {
    selfCallService.outer(1L);
    em.clear();
    System.out.println("이름: " +
            memberRepository.findById(1L).orElseThrow().getUsername());
}

